//! Opaque generated bytes isolate the HTTP state machine from FFmpeg. The gated
//! public-operation test separately verifies real generated MP4 probing.
use super::super::tests::{FakeHttp, MemoryKeychain, configured, services};
use super::*;
use std::sync::Arc;
const ID: &str = "aB_cD-eF012";
fn completed() -> String {
    format!(r#"{{"id":"{ID}","status":{{"privacyStatus":"private"}}}}"#)
}
fn fixture(
    total: usize,
) -> (
    tempfile::TempDir,
    Services,
    Record,
    Source,
    Arc<FakeHttp>,
    Vec<u8>,
) {
    let temp = tempfile::tempdir().unwrap();
    fs::create_dir(temp.path().join("exports")).unwrap();
    let path = temp.path().join("exports/sequence.mp4");
    let bytes: Vec<_> = (0..total).map(|i| (i % 251) as u8).collect();
    fs::write(&path, &bytes).unwrap();
    let mut fingerprint = stamp(&path).unwrap();
    fingerprint.sha256 = protocol::digest(&bytes);
    let source = Source {
        root: temp.path().into(),
        relative: "exports/sequence.mp4".into(),
        path: path.clone(),
        file: fs::File::open(&path).unwrap(),
        fingerprint: fingerprint.clone(),
    };
    let keychain = Arc::new(MemoryKeychain::default());
    let http = Arc::new(FakeHttp::default());
    let s = services(keychain, http.clone(), temp.path());
    let mut record = configured();
    record.pending = Some(ResumeRecord {
        request: PublishRequest {
            relative_path: "exports/sequence.mp4".into(),
            title: "Generated fixture".into(),
            description: "No actual video is uploaded".into(),
            privacy: Privacy::Unlisted,
            reviewed_connection: record.tokens.as_ref().unwrap().connection.clone(),
        },
        project_binding: "b".repeat(43),
        source: fingerprint,
        session: "https://www.googleapis.com/upload/youtube/v3/videos?upload_id=synthetic".into(),
    });
    s.vault.save(&record).unwrap();
    (temp, s, record, source, http, bytes)
}
#[test]
fn partial_acknowledgement_resends_exact_prefix_and_reports_actual_forced_privacy() {
    let (_temp, s, record, source, http, bytes) = fixture(CHUNK_BYTES + 17);
    http.push(308, Some("bytes=0-262143"), "");
    http.push(201, None, &completed());
    let mut progress = Vec::new();
    let uploaded = transfer(
        &s,
        record,
        source,
        false,
        &Cancellation::default(),
        &mut |p| progress.push(p),
    )
    .unwrap();
    assert_eq!(uploaded.privacy, Privacy::Private);
    assert_eq!(uploaded.id, ID);
    assert!(s.current().unwrap().pending.is_none());
    assert_eq!(
        progress
            .iter()
            .map(|p| p.acknowledged_bytes)
            .collect::<Vec<_>>(),
        vec![262144, bytes.len() as u64]
    );
    let requests = http.requests.lock().unwrap();
    assert_eq!(requests.len(), 2);
    assert_eq!(requests[0].body, bytes[..CHUNK_BYTES]);
    assert_eq!(requests[1].body, bytes[262144..]);
    assert_eq!(
        requests[1]
            .headers
            .iter()
            .find(|(n, _)| *n == "Content-Range")
            .unwrap()
            .1,
        format!("bytes 262144-{}/{}", bytes.len() - 1, bytes.len())
    );
}
#[test]
fn interrupted_chunk_queries_status_before_sending_remaining_bytes() {
    let (_temp, s, record, source, http, bytes) = fixture(CHUNK_BYTES + 9);
    http.replies
        .lock()
        .unwrap()
        .push_back(Err("synthetic interruption"));
    http.push(308, Some("bytes=0-1048575"), "");
    http.push(200, None, &completed());
    transfer(
        &s,
        record,
        source,
        false,
        &Cancellation::default(),
        &mut |_| {},
    )
    .unwrap();
    let requests = http.requests.lock().unwrap();
    assert_eq!(requests.len(), 3);
    assert!(requests[1].body.is_empty());
    assert_eq!(requests[2].body, bytes[CHUNK_BYTES..]);
}
#[test]
fn empty_server_resume_range_starts_at_zero_without_guessing_bytes() {
    let (_temp, s, record, source, http, bytes) = fixture(31);
    http.push(308, None, "");
    http.push(201, None, &completed());
    transfer(
        &s,
        record,
        source,
        true,
        &Cancellation::default(),
        &mut |_| {},
    )
    .unwrap();
    let requests = http.requests.lock().unwrap();
    assert!(requests[0].body.is_empty());
    assert_eq!(requests[1].body, bytes);
}
#[test]
fn cancel_and_source_change_preserve_session_and_never_send_another_chunk() {
    for change in [false, true] {
        let (temp, s, record, source, http, bytes) = fixture(CHUNK_BYTES + 13);
        http.push(308, Some("bytes=0-1048575"), "");
        let cancel = Cancellation::default();
        let stop = cancel.clone();
        let result = transfer(&s, record, source, false, &cancel, &mut |p| {
            if p.acknowledged_bytes > 0 {
                if change {
                    fs::write(temp.path().join("exports/sequence.mp4"), b"changed").unwrap();
                } else {
                    stop.cancel();
                }
            }
        });
        assert!(result.is_err());
        assert_eq!(http.requests.lock().unwrap().len(), 1);
        assert!(s.current().unwrap().pending.is_some());
        if !change {
            assert_eq!(
                fs::read(temp.path().join("exports/sequence.mp4")).unwrap(),
                bytes
            );
        }
    }
}
#[test]
fn explicit_resume_checks_completed_existing_session_without_reupload_or_new_post() {
    let (_temp, s, record, source, http, _) = fixture(101);
    http.push(200, None, &completed());
    let uploaded = transfer(
        &s,
        record,
        source,
        true,
        &Cancellation::default(),
        &mut |_| {},
    )
    .unwrap();
    assert_eq!(uploaded.privacy, Privacy::Private);
    let requests = http.requests.lock().unwrap();
    assert_eq!(requests.len(), 1);
    assert!(requests[0].body.is_empty());
    assert!(matches!(requests[0].method, Method::Put));
}
#[test]
fn invalid_or_expired_session_never_creates_another_upload() {
    for (status, range) in [
        (308, Some("bytes=1-7")),
        (308, Some("bytes=0-9999")),
        (404, None),
        (403, None),
    ] {
        let (_temp, s, record, source, http, bytes) = fixture(100);
        http.push(status, range, "");
        assert!(
            transfer(
                &s,
                record,
                source,
                true,
                &Cancellation::default(),
                &mut |_| {}
            )
            .is_err()
        );
        assert_eq!(http.requests.lock().unwrap().len(), 1);
        assert!(s.current().unwrap().pending.is_some());
        assert_eq!(bytes.len(), 100);
    }
}
#[test]
fn retry_budget_is_bounded_even_when_status_succeeds_without_new_bytes() {
    let (_temp, s, record, source, http, _) = fixture(50);
    for _ in 0..5 {
        http.replies
            .lock()
            .unwrap()
            .push_back(Err("synthetic interruption"));
        http.push(308, None, "");
    }
    assert!(
        transfer(
            &s,
            record,
            source,
            false,
            &Cancellation::default(),
            &mut |_| {}
        )
        .is_err()
    );
    assert_eq!(http.requests.lock().unwrap().len(), 9);
    assert!(s.current().unwrap().pending.is_some());
}
#[test]
fn ranges_and_sessions_metadata_validation_are_bounded_and_private_default_is_unlisted() {
    assert_eq!(Privacy::default(), Privacy::Unlisted);
    assert_eq!(protocol::acknowledged(None, 1000, 1000).unwrap(), 0);
    assert_eq!(
        protocol::acknowledged(Some("bytes=0-99"), 1000, 100).unwrap(),
        100
    );
    for range in [
        "bytes=1-99",
        "bytes=0-1000",
        "bytes=0-18446744073709551615",
        "bytes=0--1",
        "bytes=0-1,2-3",
    ] {
        assert!(protocol::acknowledged(Some(range), 1000, 100).is_err());
    }
    for uri in [
        "http://www.googleapis.com/upload/youtube/v3/videos?upload_id=x",
        "https://evil.example/upload/youtube/v3/videos?upload_id=x",
        "https://user@www.googleapis.com/upload/youtube/v3/videos?upload_id=x",
        "https://www.googleapis.com/other?upload_id=x",
        "https://www.googleapis.com/upload/youtube/v3/videos?upload_id=x&upload_id=y",
    ] {
        assert!(protocol::validate_session_url(uri).is_err());
    }
    let (_temp, _s, record, _source, _http, _) = fixture(12);
    let mut request = record.pending.unwrap().request;
    request.title = "标题".repeat(50);
    request.description = "é".repeat(2500);
    assert!(request.validate().is_ok());
    request.title.push('x');
    assert!(request.validate().is_err());
    request.title = "Valid".into();
    request.description.push('x');
    assert!(request.validate().is_err());
    request.description.clear();
    request.relative_path = "../outside.mp4".into();
    assert!(request.validate().is_err());
}
